import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { nameParkings, ParkingsResponse, type Parking } from '@vlaiq/shared';
import { cityData } from './cityData';

// Generated by `pnpm data:parkings` (scripts/fetch-osm-parkings.mjs). Real OSM data, never hand-invented.
const DATA_FILE = fileURLToPath(new URL('../../../shared/src/data/parkings.osm.json', import.meta.url));

const EMPTY: ParkingsResponse = {
  parkings: [],
  dataset: { source: 'none — run `pnpm data:parkings`', generatedAt: null, attribution: '© OpenStreetMap contributors' },
};

function load(): ParkingsResponse {
  if (!existsSync(DATA_FILE)) {
    console.warn(`[parkings] ${DATA_FILE} not found — serving an empty list. Run \`pnpm data:parkings\`.`);
    return EMPTY;
  }
  const parsed = ParkingsResponse.safeParse(JSON.parse(readFileSync(DATA_FILE, 'utf8')));
  if (!parsed.success) {
    console.error('[parkings] data file does not match the Parking schema:', parsed.error.issues.slice(0, 5));
    return EMPTY;
  }
  // Neighbourhood for every parking; a position-based name for the ones OSM leaves unnamed.
  const parkings = nameParkings(parsed.data.parkings, {
    neighbourhoods: cityData.neighbourhoodFeatures(),
    osmStreets: cityData.osmStreetList(),
  });
  const derived = parkings.filter((p) => p.nameIsDerived).length;
  console.log(`[parkings] ${parkings.length} OSM parkings (${derived} with a position-based name)`);
  return { ...parsed.data, parkings };
}

const store = load();

export const parkingStore = {
  all: (): ParkingsResponse => store,
  byId: (id: string): Parking | undefined => store.parkings.find((p) => p.id === id),
  count: (): number => store.parkings.length,
};
